const cfg = $('Config').first().json;

const taken = new Set(
  $('Get log rows').all()
    .map(i => i.json)
    .filter(r => r.url && ['posted', 'pending', 'scheduled'].includes(r.status))
    .map(r => r.url)
);

const fresh = $('Parse sitemap').all().filter(i => !taken.has(i.json.url));

if (!fresh.length) {
  throw new Error('No unposted items left among the newest ' + cfg.candidates + ' sitemap entries');
}

return [{ json: { ...fresh[Math.min(cfg.pick_index, fresh.length - 1)].json, run_id: 'run-' + Date.now() } }];

const xml = $input.first().json.data;
const cfg = $('Config').first().json;

const blocks = xml.match(/<url>[\s\S]*?<\/url>/g) || [];
const items = blocks.map(b => ({
  url: ((b.match(/<loc>\s*([^<]+?)\s*<\/loc>/) || [])[1] || '').replace(/&amp;/g, '&'),
  lastmod: (b.match(/<lastmod>\s*([^<]+?)\s*<\/lastmod>/) || [])[1] || '',
  content_type: cfg.content_type
})).filter(i => i.url);

if (!items.length) {
  throw new Error('Sitemap returned no URLs - site down or format changed');
}

items.sort((a, b) => b.lastmod.localeCompare(a.lastmod));

return items.slice(0, cfg.candidates).map(i => ({ json: i }));

const html = $input.first().json.data;
const item = $('Select item').first().json;

const decode = s => (s || '')
  .replace(/&quot;/g, '"').replace(/&#0?39;/g, "'").replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ')
  .replace(/&yen;/g, '¥').replace(/&ndash;/g, '–').replace(/&mdash;/g, '—')
.replace(/&[lr]squo;/g, "'").replace(/&[lr]dquo;/g, '"').replace(/&#(\d+);/g, (m, n) => String.fromCharCode(+n));

const meta = (prop) => {
  const a = new RegExp('<meta[^>]*?(?:property|name)=(["\'])' + prop + '\\1[^>]*?content=(["\'])([\\s\\S]*?)\\2', 'i');
  const b = new RegExp('<meta[^>]*?content=(["\'])([\\s\\S]*?)\\1[^>]*?(?:property|name)=(["\'])' + prop + '\\3', 'i');
  let m = html.match(a);
  if (m) return decode(m[3]).trim();
  m = html.match(b);
  return m ? decode(m[2]).trim() : '';
};

const stripped = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<(nav|header|footer|aside)[\s\S]*?<\/\1>/gi, ' ');

const paras = (stripped.match(/<(p|li|h2|h3)[^>]*>[\s\S]*?<\/\1>/gi) || [])
  .map(p => decode(p.replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim())
  .filter(t => t.length > 40);

const body = paras.join('\n').slice(0, 4000);

const out = {
  ...item,
  title: meta('og:title') || decode((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '').trim(),
  summary: meta('og:description') || meta('description'),
  image_url: meta('og:image'),
  body,
  body_chars: body.length
};

if (!out.title || (!out.summary && out.body_chars < 200)) {
  throw new Error('Could not extract usable content from ' + item.url);
}

return [{ json: out }];

