const cfg = $('Config').first().json;
const r = $('Rule check').first().json;
const input = $input.first().json;
const raw = input.text ?? (input.response && input.response.text) ?? '';

let verdict;
try {
  const cleaned = String(raw).replace(/```json|```/gi, '').trim();
  verdict = JSON.parse(cleaned.slice(cleaned.indexOf('{'), cleaned.lastIndexOf('}') + 1));
} catch (e) {
  verdict = { pass: false, violations: ['Verifier returned unreadable output'] };
}

const llmPass = verdict.pass === true;
const llmViolations = llmPass ? [] :
  (Array.isArray(verdict.violations) && verdict.violations.length ? verdict.violations : ['Verifier rejected the post'])
    .map(v => 'LLM check: ' + v);

const violations = [...r.rule_violations, ...llmViolations];
const passed = r.rules_passed && llmPass;
const route = passed ? 'pass' : (r.attempt < cfg.max_attempts ? 'retry' : 'blocked');

return [{ json: { ...r, llm_pass: llmPass, guardrail_passed: passed, violations, feedback: violations.join(' | '), route } }];

const d = $input.first().json;
return [{ json: {
  run_id: d.run_id,
  url: d.url,
  content_type: d.content_type,
  title: d.title,
  post_text: d.post_text,
  image_url: d.image_url || ''
} }];

const p = $('Final post').first().json;
return [{ json: {
  run_id: p.run_id,
  status: 'simulated',
  fb_post_id: 'SIMULATED-' + Date.now(),
  error: ''
} }];

const cfg = $('Config').first().json;
const p = $('Final post').first().json;
const mins = Number(cfg.schedule_minutes || 0);
const useImage = !!p.image_url && mins === 0;

const body = useImage
  ? { url: p.image_url, caption: p.post_text }
  : { message: p.post_text };

if (mins > 0) {
  body.published = false;
  body.scheduled_publish_time = Math.floor(Date.now() / 1000) + Math.max(mins, 11) * 60;
}

return [{ json: { run_id: p.run_id, endpoint: useImage ? 'photos' : 'feed', body } }];

const j = $input.first().json;
const p = $('Plan publish').first().json;
return [{ json: {
  run_id: p.run_id,
  status: p.body.published === false ? 'scheduled' : 'posted',
  fb_post_id: j.post_id || j.id || '',
  error: ''
} }];

const j = $input.first().json;
const p = $('Plan publish').first().json;
const msg = JSON.stringify(j.error || j).slice(0, 500);
const tokenBad = /"code":\s*190|OAuthException|access token/i.test(msg);
return [{ json: {
  run_id: p.run_id,
  status: 'failed',
  fb_post_id: '',
  error: (tokenBad ? 'FACEBOOK TOKEN EXPIRED OR INVALID - refresh the Page token. ' : '') + msg
} }];

const j = $input.first().json;
const p = $('Final post').first().json;
const flag = (j.data && j.data.approved !== undefined) ? j.data.approved : j.approved;
const approved = flag === true || flag === 'true';
const rejected = flag === false || flag === 'false';
return [{ json: {
  run_id: p.run_id,
  approved,
  status: approved ? 'approved' : (rejected ? 'rejected' : 'expired'),
  fb_post_id: '',
  error: approved ? '' : (rejected ? 'Rejected by reviewer' : 'No response within the approval window')
} }];
